# Traitez des fichiers CSV
import csv
from collections import defaultdict

def charger(chemin):
    with open(chemin, encoding="utf-8-sig", newline="") as f:
        reader = csv.DictReader(f)
        return list(reader)

notes = charger("effectif.csv")

# Regrouper les notes par matière
par_matiere = defaultdict(list)
for note in notes:
    for matiere in note:
        if matiere != "nom":
            par_matiere[matiere].append(float(note[matiere]))

# Calculer les moyennes
moyennes = {matiere: sum(valeurs) / len(valeurs) for matiere, valeurs in par_matiere.items()}

# Afficher le rapport
for matiere, moyenne in sorted(moyennes.items()):
    print(f"{matiere} : {moyenne:.2f}")
